arguments.new_string:
buf = []
splits_done = 0
for item in iterable:
    buf.append(item)
    if pred(item):
        if maxsplit is None or splits_done < maxsplit:
            yield buf
            splits_done += 1
            buf = []
        # else: reached maxsplit, keep accumulating
if buf:
    yield buf
